function drawOverlay(){
 if(state==='run')return;
 ctx.fillStyle='#101d43a8';ctx.fillRect(0,0,W,H);
 const panelX=255,panelY=state==='ready'?118:135,panelW=450,panelH=state==='ready'?284:246;
 ctx.fillStyle='#182a57eF';rr(panelX,panelY,panelW,panelH,27);ctx.fill();ctx.strokeStyle='#ffffff2a';ctx.lineWidth=2;rr(panelX+1,panelY+1,panelW-2,panelH-2,26);ctx.stroke();
 if(state==='ready'){
  // twinkly badge
  ctx.fillStyle='#ffe68d';ctx.font='bold 15px system-ui';ctx.textAlign='center';ctx.fillText('✦  THE NIGHT IS YOURS  ✦',480,163);
  ctx.fillStyle='#f8f6ff';ctx.font='900 48px ui-rounded,system-ui';ctx.fillText('Oi!',480,224);
  ctx.fillStyle='#b9c9ed';ctx.font='600 17px system-ui';ctx.fillText('Hop over the sleepy slimes.',480,258);ctx.fillText('Collect stars. See how far you get!',480,284);
  ctx.fillStyle='#9bf0bb';ctx.beginPath();ctx.arc(480,327,26,0,Math.PI*2);ctx.fill();ctx.fillStyle='#25446a';ctx.font='bold 23px system-ui';ctx.fillText('↑',480,335);
  ctx.fillStyle='#dce6ff';ctx.font='700 13px system-ui';ctx.fillText('TAP TO START',480,376);
 }else{
  ctx.fillStyle='#ffae9b';ctx.font='bold 14px system-ui';ctx.textAlign='center';ctx.fillText('THAT WAS A NICE LITTLE RUN',480,178);
  ctx.fillStyle='#f8f6ff';ctx.font='900 38px ui-rounded,system-ui';ctx.fillText('Bonk!',480,230);
  ctx.fillStyle='#bdc9e6';ctx.font='600 16px system-ui';ctx.fillText('You scored',480,263);
  ctx.fillStyle='#ffe486';ctx.font='900 39px ui-rounded,system-ui';ctx.fillText(String(Math.floor(score)).padStart(3,'0'),480,311);
  ctx.fillStyle='#a5efbd';ctx.font='bold 13px system-ui';ctx.fillText('TAP TO TRY AGAIN',480,350);
 }
}
function draw(t){drawBackground(t);stars.forEach(s=>drawStar(s,t));obstacles.forEach(o=>drawObstacle(o,t));drawPlayer(t);for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;drawOverlay()}
function frame(now){const dt=Math.min(.05,(now-last)/1000||0);last=now;update(dt);draw(now/1000);requestAnimationFrame(frame)}
requestAnimationFrame(now=>{last=now;frame(now)});
})();
</script>
